(() => {
  let res = result;
  try {
    const body = String(res.body());
    if (/fffffffffffffffffff/.test(body) || /\/C2WF\w+\/probe\.js/.test(body)) {
      const target = String(java.ruleUrl || java.url || "");
      java.initUrl();
      const ck = java.webView(null, target, "document.cookie");
      if (ck) {
        try { cookie.setCookie(target, ck); } catch (e) {}
      }
      res = java.getStrResponse();
      const b2 = String(res.body());
      if (/fffffffffffffffffff/.test(b2) || /\/C2WF\w+\/probe\.js/.test(b2)) {
        const html = java.webView(null, target, "document.documentElement.outerHTML");
        if (html && !/fffffffffffffffffff/.test(String(html))) {
          res = java.getStrResponse();
        }
      }
    }
  } catch (e) {
    java.log("loginCheckJs WAF: " + e);
  }
  return res;
})();

