@js:
let content;
if (chapter.isVip()) {
    function isLatest(t) {
        return ((t = new Date(String(t).replace(/-/g, "/")).getTime()), Date.now() - t <= 1728e5);
    }
    if (isLatest(String(chapter.tag))) throw new Error("暂未更新");
    let t = baseUrl.match(/\/(\d+)\/(\d+)\//),
        e = `${host}/qd/content?bookId=${t[1]}&chapterId=${t[2]},{"headers":${source.getVariable()}}`,
        a = java.ajax(e);
    if (((a = JSON.parse(a)), !(content = a.data))) throw new Error(a.msg);
} else {
    let t = baseUrl.match(/\/(\d+)\/(\d+)\//),
        e = java.ajax(host + "/qd/fcontent?bookId=" + t[1] + "&chapterId=" + t[2]);
    if (((e = JSON.parse(e)), !(content = e.data))) throw new Error(e.msg);
}
content;

