ruleToc.chapterList:
@js:const bid = baseUrl.match(/\/book\/(\d+)\/?/)[1];
const cps = java.ajax(`https://s6.nethogs01.de/qd/catalog?bookId=${bid}`)
let cataData = JSON.parse(cps);
let chapters = cataData.Data.Chapters;
let volumes = cataData.Data.Volumes;

let volumeMap = volumes.reduce((acc, v) => {
  acc[v.VolumeCode] = v.VolumeName;
  return acc;
}, {});

let volSet = new Set();
let data = chapters.reduce((arr, item, index) => {
  let title = item.N.replace('版权信息', '');

  let url = `http://example.com/chapter/${bid}/${item.C}/`;

  // 新卷
  if (!volSet.has(item.Vc)) {
    arr.push({
      title: volumeMap[item.Vc],
      url: '',
      vid: item.Vc,
      vol: true
    });
    volSet.add(item.Vc);
  }

  let time = java.timeFormat(item.T);
  let vip = item.V;

  arr.push(
    JSON.stringify({
      title,
      url,
      time,
      vip
    })
  );

  return arr;
}, []);
data;

