ruleContent.replaceRegex:
@js:
var content = result;
// Fix 1: Remove start ads with parentheses - pattern: (闃呰搴?..com)(闃呰搴?..com)
content = content.replace(/^\s*[\(]\s*\u9605\u8BFB\u5E93\s*www\.yeudusk\.com[^)]*[\)]\s*[\(]\s*\u9605\u8BFB\u5E93\s*www\.yeudusk\.com[^)]*[\)]\s*/g, '');
// Fix 2: Remove end ads without parentheses - pattern: 闃呰搴?www.yeudusk.comyeudusk www.yeudusk.com
content = content.replace(/\u9605\u8BFB\u5E93\s*www\.yeudusk\.com\s*yeudusk\s*www\.yeudusk\.com\s*$/g, '');
// Fix 3: Remove recommendation text
content = content.replace(/\u9605\u8BFB\u5E63\u8350\u4F1D\u5404\u4F4D\u4E66\u53CB\u9605\u8BFB[^<]*/g, '');
// Fix 4: Clean up excessive <br> tags (more than 2 in a row)
content = content.replace(/(<br\s*\/?>[\s&nbsp;]*){3,}/gi, '<br /><br />&nbsp;&nbsp;&nbsp;&nbsp;');
// Return cleaned content
content;

